import { expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  for (const extraction of Object.values(extractions)) {
    const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
      data: { decision: "approve" },
    });
    const body = await expectStatus(response, 200);
    expect(body.status).toBe("approved");
  }

  // Assert
  // Re-read the stored vendor rather than trusting any response echo.
  await expect
    .poll(
      async () => (await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200)).status,
      { message: "vendor status becomes approved once every extraction is approved", timeout: 15_000 },
    )
    .toBe("approved");

  await expect
    .poll(
      async () => {
        const audit = await expectStatus<{ items: { action: string }[] }>(
          await reviewer.get(`/api/vendors/${vendor.id}/audit`),
          200,
        );
        return audit.items.map((event) => event.action);
      },
      { message: "audit trail records vendor.approved", timeout: 15_000 },
    )
    .toContain("vendor.approved");
});
